<template><view class="page"><view class="tabs"><text v-for="t in tabs" :key="t.v" :class="{active:status===t.v}" @tap="status=t.v;load()">{{t.l}}</text></view><view v-for="i in list" :key="i.id" class="card"><view class="top"><b>{{i.dataTypeText||i.dataType}}异常提醒</b><text :class="i.alertLevel==='HIGH'?'danger':''">{{i.alertLevel}}</text></view><view class="value">记录值：{{i.measuredValue}}</view><view class="time">{{i.createTime}} · {{i.statusText||i.status}}</view></view><view v-if="!list.length" class="empty">暂无异常提醒</view></view></template><script>import{getHealthAlerts}from'@/api/health.js';export default{data(){return{status:'',list:[],tabs:[{l:'全部',v:''},{l:'待处理',v:'OPEN'},{l:'已关注',v:'ACKNOWLEDGED'},{l:'已关闭',v:'CLOSED'}]}},onShow(){this.load()},methods:{load(){getHealthAlerts({status:this.status,page:1,limit:100}).then(r=>{const d=r&&r.data?r.data:r;this.list=(d&&d.list)||d||[]})}}}</script><style lang="scss" scoped>.page{min-height:100vh;background:#f6f7f8;padding:24rpx}.tabs{display:flex;background:#fff;border-radius:18rpx;padding:14rpx;margin-bottom:18rpx}.tabs text{flex:1;text-align:center;padding:12rpx}.active{background:#19bf9b;color:#fff;border-radius:99rpx}.card{background:#fff;border-radius:20rpx;padding:24rpx;margin-bottom:16rpx}.top{display:flex;justify-content:space-between}.value{font-size:32rpx;margin:20rpx 0}.time{color:#999;font-size:23rpx}.danger{color:#e44}.empty{text-align:center;padding:100rpx;color:#aaa}</style>